(() => {
    const rows = invoicesQuery.data || [];
    const unpaid = rows.filter(
      (i) => i.status === "open" || i.status === "uncollectible"
    );
    if (unpaid.length === 0) return null;

    // SCOPE TO THE CURRENT SUBSCRIPTION.
    //
    // Invoices are stored per TENANT, so an unfiltered read picks up debts that
    // belong to a subscription that is dead and gone. Observed in production: a
    // tenant with a healthy trialing subscription was shown "Payment failed —
    // your invoice of $1.00 is unpaid", where the invoice came from a DIFFERENT,
    // abandoned checkout — and in a different Stripe mode. A tenant cannot pay
    // their way out of that: settling the current subscription changes nothing,
    // because the warning is anchored on someone else's invoice.
    //
    // This is not cosmetic. openInvoice also anchors the 7-day grace clock, so a
    // stale invoice can expire the window instantly and hard-block a tenant who
    // owes nothing.
    //
    // An unlinked invoice (subscription_id NULL — an orphan we could not
    // attribute) is admitted ONLY if it is not older than the subscription
    // itself: an invoice raised before this subscription existed cannot be its
    // debt.
    const current = subscriptionQuery.data;
    const mine = current
      ? unpaid.filter((i) =>
          i.subscription_id
            ? i.subscription_id === current.id
            : new Date(invoiceDateOf(i)).getTime() >=
              new Date(current.created_at).getTime(),
        )
      : // No live subscription: keep every unpaid invoice in play, so a tenant
        // whose subscription Stripe already cancelled still gets a pay link
        // rather than silently losing the debt.
        unpaid;

    if (mine.length === 0) return null;
    // Oldest unpaid — that is the one whose clock started first. Compared on
    // Stripe's date, not our insert time, so a reconciler backfill cannot
    // reorder which invoice anchors the grace window.
    return mine.reduce((a, b) =>
      new Date(invoiceDateOf(a)).getTime() <= new Date(invoiceDateOf(b)).getTime() ? a : b
    );
  })

(() => {
    if (!isPastDue) return null;
    // NO open invoice means nothing is actually overdue — do NOT fall back to
    // current_period_start.
    //
    // That fallback silently defeated the whole point of closing an invoice out.
    // When support voids a failed invoice as goodwill, the only open invoice
    // disappears; the fallback then anchored the clock on a
    // current_period_start already weeks in the past, so graceEndsAt was
    // instantly expired and the tenant stayed hard-blocked — over an invoice
    // Stripe considers settled, with a "pay your pending invoice" link they
    // could not act on. It also mis-fired for any past_due tenant whose invoice
    // rows had not synced.
    //
    // Returning null here means graceEndsAt is null, which isSubscribed already
    // treats as fail-open ("past_due with no resolvable anchor must not lock
    // anyone out"). Nothing overdue, no block.
    const anchor = openInvoice?.period_end || (openInvoice ? invoiceDateOf(openInvoice) : null);
    if (!anchor) return null;
    const t = new Date(anchor).getTime();
    return Number.isNaN(t) ? null : t;
  })

(() => {
    if (!isTrialing || !subscriptionQuery.data?.trial_end) return 0;
    const now = new Date();
    const trialEnd = new Date(subscriptionQuery.data.trial_end);
    const diff = Math.ceil((trialEnd.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
    return Math.max(0, diff);
  })
